package com.healthcompanion.security;
import com.healthcompanion.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; private final UserRepository users; public JwtAuthenticationFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")) try {var u=users.findById(jwt.userId(h.substring(7))).orElseThrow(); var a=new UsernamePasswordAuthenticationToken(u.id,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.role))); SecurityContextHolder.getContext().setAuthentication(a);} catch(Exception ignored){} chain.doFilter(req,res);}
}
